-- @@BLOQUE trazabilidad
-- Trazabilidad: fechas de las notificaciones que crearon los triggers
UPDATE public.notificaciones n SET fecha_creacion = coalesce(
    (SELECT p.fecha_creacion FROM public.propuestas p WHERE p.id = n.propuesta_id AND n.tipo::text = 'nueva_propuesta'),
    (SELECT p.fecha_actualizacion FROM public.propuestas p WHERE p.id = n.propuesta_id),
    (SELECT s.fecha_creacion FROM public.solicitudes s WHERE s.id = n.solicitud_id AND n.tipo::text = 'nueva_solicitud'),
    (SELECT s.fecha_actualizacion FROM public.solicitudes s WHERE s.id = n.solicitud_id),
    n.fecha_creacion)
  WHERE n.fecha_creacion > now() - interval '60 minutes' AND (n.solicitud_id IS NOT NULL OR n.propuesta_id IS NOT NULL);
-- Las notificaciones de más de 2 días quedan leídas, como en una cuenta en uso.
UPDATE public.notificaciones SET leida = true WHERE fecha_creacion < now() - interval '2 days' AND NOT leida AND usuario_id IN ('d604c7bd-505d-47e7-bd27-12bb4b65b916', '061d3a2a-ebd9-4d3d-86e3-2a8716a37a6d', '6290ffb3-c285-4edd-a50b-61b4c46e1cf9', 'a13af6d8-25db-4590-8d53-5df9a71604cb', '2c495cc5-3f76-4200-897a-061fc73674a0', '705e242a-b796-4d71-adaa-3045d45fe400', 'c86ccc47-1df0-464a-9a5d-26267960fff0', 'c57e4122-89ba-4ede-b339-4b3ab4eb2f4a', '5775d9f1-d556-494d-93d9-7b1d57289220', '9d7a3784-ae8e-4674-ab73-864a9138d65f', '141bc251-caef-47c6-bea4-2d9a2533b4b0', '784e90c9-156a-4c80-92a7-8fd48a9c3a64', 'cdb8c08e-409b-4211-9db8-06cf6e958ca7', '803a76a9-b719-4b2d-8a66-6d62a279dbf6', '0c44fa0c-3ea7-4c9a-bf47-3f1ef17fd895', '5d3425dd-b087-48b1-9aca-c94acec06245', '43b35021-77c4-4e5c-9619-1f50493ba70f');
